CREATE TABLE join_demo_users (
    id integer PRIMARY KEY,
    name text NOT NULL
);
CREATE TABLE join_demo_tasks (
    id integer PRIMARY KEY,
    owner_id integer NOT NULL REFERENCES join_demo_users(id)
);
CREATE TABLE join_demo_payments (
    id integer PRIMARY KEY,
    owner_id integer NOT NULL REFERENCES join_demo_users(id),
    amount integer NOT NULL CHECK (amount >= 0)
);
