SELECT id, owner_id,
       ROW_NUMBER() OVER (
         PARTITION BY owner_id ORDER BY id DESC
       ) AS rn
FROM tasks
ORDER BY owner_id, rn;

WITH events(id, owner_id, at_minute, amount) AS (
    VALUES (1, 1, 600, 10), (2, 1, 600, 20), (3, 1, 601, 5)
)
SELECT id, at_minute, amount,
       SUM(amount) OVER (
           PARTITION BY owner_id ORDER BY at_minute
       ) AS default_total,
       SUM(amount) OVER (
           PARTITION BY owner_id ORDER BY at_minute
           RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS explicit_range_total
FROM events
ORDER BY at_minute, id;

WITH events(id, owner_id, at_minute, amount) AS (
    VALUES (1, 1, 600, 10), (2, 1, 600, 20), (3, 1, 601, 5)
)
SELECT at_minute,
       COUNT(*) OVER (
           PARTITION BY owner_id ORDER BY at_minute
       ) AS range_size,
       COUNT(*) OVER (
           PARTITION BY owner_id ORDER BY at_minute
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS rows_size
FROM events
ORDER BY at_minute, rows_size;

WITH events(id, owner_id, at_minute, amount) AS (
    VALUES (1, 1, 600, 10), (2, 1, 600, 20), (3, 1, 601, 5)
)
SELECT id,
       SUM(amount) OVER (
           PARTITION BY owner_id ORDER BY at_minute, id
       ) AS default_unique_total,
       SUM(amount) OVER (
           PARTITION BY owner_id ORDER BY at_minute, id
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS rows_total
FROM events
ORDER BY at_minute, id;

SELECT id, title FROM tasks
WHERE id > 11
ORDER BY id LIMIT 2;

